<script setup>
import { computed,onBeforeUnmount,onMounted,nextTick,ref } from 'vue'
import { api } from './api'
const conversations=ref([]),messages=ref([]),selectedId=ref(null),reply=ref(''),loading=ref(false),sending=ref(false),error=ref(''),pane=ref(null)
const selected=computed(()=>conversations.value.find(c=>c.id===selectedId.value)||null)
let timer=null
function name(c){return c?.contact?.name||c?.contact?.username||String(c?.chat_id||'Telegram')}
function time(v){if(!v)return'';return new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit'}).format(new Date(v))}
async function bottom(){await nextTick();if(pane.value)pane.value.scrollTop=pane.value.scrollHeight}
async function load({auto=true}={}){try{conversations.value=await api.telegramConversations();if(auto&&!selectedId.value&&conversations.value.length)await select(conversations.value[0].id)}catch(e){error.value=e.message}}
async function select(id){selectedId.value=id;loading.value=true;error.value='';try{messages.value=await api.telegramMessages(id);await api.telegramMarkRead(id);await load({auto:false});await bottom()}catch(e){error.value=e.message}finally{loading.value=false}}
async function refresh(){try{await load({auto:false});if(selectedId.value){const latest=await api.telegramMessages(selectedId.value);if(latest.length!==messages.value.length||latest.some((m,i)=>m.id!==messages.value[i]?.id)){messages.value=latest;await api.telegramMarkRead(selectedId.value);await load({auto:false});await bottom()}}}catch(_){}}
async function send(){const text=reply.value.trim();if(!selected.value||!text||sending.value)return;sending.value=true;error.value='';try{messages.value.push(await api.telegramSendText(selected.value.id,text));reply.value='';await load({auto:false});await bottom()}catch(e){error.value=e.message}finally{sending.value=false}}
onMounted(async()=>{await load();timer=setInterval(refresh,3000)});onBeforeUnmount(()=>timer&&clearInterval(timer))
</script>
<template><div class="tg-chat"><aside class="tg-list"><header><div><p>TELEGRAM</p><h2>Conversations</h2></div><button @click="load({auto:false})">↻</button></header><div v-if="!conversations.length" class="empty">No Telegram conversations yet.<small>Send your bot a message and it will appear here.</small></div><button v-for="c in conversations" :key="c.id" class="row" :class="{active:c.id===selectedId,unread:c.unread_count}" @click="select(c.id)"><span class="avatar">{{name(c).slice(0,1).toUpperCase()}}</span><span class="copy"><span><b>{{name(c)}}</b><time>{{time(c.last_message_at)}}</time></span><small>{{c.last_message_direction==='outbound'?'You: ':''}}{{c.last_message_body||'Telegram message'}}</small><i>@{{c.contact.username||'telegram'}} · {{c.bot.first_name||c.bot.username}}</i></span><em v-if="c.unread_count">{{c.unread_count}}</em></button></aside>
<section class="chat"><template v-if="selected"><header><div class="avatar large">{{name(selected).slice(0,1).toUpperCase()}}</div><div><b>{{name(selected)}}</b><span>@{{selected.contact.username||selected.contact.telegram_user_id}} · via @{{selected.bot.username}}</span></div></header><div ref="pane" class="messages"><div v-if="loading" class="loading">Loading…</div><article v-for="m in messages" :key="m.id" :class="m.direction"><div><span v-if="m.message_type!=='text'" class="type">{{m.message_type}}</span><p>{{m.body||`[${m.message_type}]`}}</p><time>{{time(m.telegram_timestamp||m.created_at)}}</time></div></article></div><form class="composer" @submit.prevent="send"><textarea v-model="reply" rows="2" placeholder="Reply on Telegram…" @keydown.enter.exact.prevent="send"></textarea><button :disabled="sending||!reply.trim()">{{sending?'Sending…':'Send'}}</button></form></template><div v-else class="no-chat"><div>T</div><h2>Telegram Live Chat</h2><p>Send your connected bot a message to start the first conversation.</p></div><p v-if="error" class="error">{{error}}</p></section></div></template>
<style scoped>
.tg-chat{height:calc(100vh - 150px);min-height:560px;background:#fff;border:1px solid #dce5e1;border-radius:14px;display:grid;grid-template-columns:330px minmax(0,1fr);overflow:hidden;box-shadow:0 3px 14px rgba(21,57,43,.04)}.tg-list{border-right:1px solid #e2e9e6;overflow:auto}.tg-list header,.chat header{display:flex;align-items:center;padding:18px;border-bottom:1px solid #e8eeeb}.tg-list header{justify-content:space-between}.tg-list header p{margin:0;color:#229ed9;font-size:9px;font-weight:900;letter-spacing:.1em}.tg-list h2{margin:2px 0 0;font-size:18px}.tg-list header button{border:1px solid #d8e2de;background:#fff;border-radius:7px;padding:7px 9px;cursor:pointer}.row{position:relative;width:100%;display:flex;gap:10px;padding:14px 15px;border:0;border-bottom:1px solid #edf1ef;background:#fff;text-align:left;cursor:pointer}.row:hover,.row.active{background:#f1f8f5}.row.unread{background:#f2faff}.avatar{width:38px;height:38px;flex:0 0 auto;border-radius:50%;display:grid;place-items:center;background:#dff3fc;color:#1688bc;font-weight:900}.avatar.large{width:42px;height:42px}.copy{min-width:0;flex:1}.copy>span{display:flex;justify-content:space-between;gap:8px}.copy b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.copy time,.copy small,.copy i{font-size:10px;color:#87978f}.copy small,.copy i{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px}.copy i{font-style:normal;color:#229ed9}.row em{align-self:center;background:#229ed9;color:#fff;border-radius:999px;min-width:18px;height:18px;display:grid;place-items:center;font-size:9px;font-style:normal}.empty{padding:35px 20px;text-align:center;color:#74867e}.empty small{display:block;margin-top:6px}.chat{min-width:0;display:flex;flex-direction:column;position:relative}.chat header{gap:10px}.chat header b,.chat header span{display:block}.chat header span{margin-top:3px;color:#809188;font-size:11px}.messages{flex:1;overflow:auto;padding:22px;background:#f5f8f7}.messages article{display:flex;margin:7px 0}.messages article.inbound{justify-content:flex-start}.messages article.outbound{justify-content:flex-end}.messages article>div{max-width:70%;padding:9px 11px;border-radius:11px;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.05)}.messages article.outbound>div{background:#dff5eb}.messages p{margin:0;white-space:pre-wrap;line-height:1.45}.messages time{display:block;text-align:right;margin-top:4px;color:#87968f;font-size:9px}.type{display:inline-block;margin-bottom:5px;padding:2px 5px;border-radius:4px;background:#e6f3f9;color:#147ca9;font-size:8px;font-weight:800;text-transform:uppercase}.composer{display:flex;gap:10px;padding:13px;border-top:1px solid #e0e8e4;background:#fff}.composer textarea{flex:1;resize:none;border:1px solid #cfddd7;border-radius:9px;padding:10px;font:inherit}.composer button{align-self:stretch;border:0;border-radius:9px;background:#229ed9;color:#fff;padding:0 20px;font-weight:800;cursor:pointer}.composer button:disabled{opacity:.5}.no-chat{margin:auto;text-align:center;color:#74867e}.no-chat div{width:54px;height:54px;margin:auto;border-radius:16px;background:#229ed9;color:#fff;display:grid;place-items:center;font-size:23px;font-weight:900}.no-chat h2{color:#173026}.error{position:absolute;left:15px;right:15px;bottom:15px;background:#fff0f0;color:#992d2d;padding:9px;border-radius:7px}@media(max-width:800px){.tg-chat{grid-template-columns:1fr;height:auto}.tg-list{max-height:300px;border-right:0;border-bottom:1px solid #e2e9e6}.chat{min-height:520px}}
</style>